60	// W4-Compile-Gate: die Mess-Pfad-Kompositionen sind die REALEN Katalog-Lebewesen (compile-time praesent, KEIN
61	// Surrogat-Typ). Genau diese Typen emittiert sota_catalog.hpp als COMDARE_DEFINE_ANATOMY_MODULE-Quelle.
62	static_assert(!std::string_view{comp::HotComposition::name}.empty(),
