69	/// KatalogPermutationOutcome -- das Mess-Ergebnis EINER Permutation ueber den realen Katalog-Pfad. Spiegelt die
70	/// Mess-Felder von v32::PermutationOutcome (ee_a/ee_b/verdict/welch/throughput), ist aber BEWUSST eigenstaendig,
71	/// damit dieser Header KEINE Surrogat-Adapter (v32_orchestrator.hpp) einzieht -> W4-rein (grep-belegt).
72	struct KatalogPermutationOutcome {
73	    std::string                        axis_id;
74	    std::string                        variant_name;
75	    cmd::ExecutionResult               ee_a_result; ///< Stufe1_CeOnly-Katalog-Tier (echte Per-Op-Latenzen)
76	    cmd::ExecutionResult               ee_b_result; ///< Stufe2_PrueflingReplace-Katalog-Tier (echte Per-Op-Latenzen)
77	    cmd::CompareEngineCommand::Verdict verdict{cmd::CompareEngineCommand::Verdict::InconclusiveData};
78	    double                             welch_p_value{1.0};
79	    double                             throughput_ratio{0.0};
80	    std::uint64_t                      ee_a_conformance_cases{0}; ///< Pruefdock: geprueften std::map-Zusicherungen
81	    std::uint64_t                      ee_b_conformance_cases{0};
82	    bool                               ee_a_conformance_passed{false};
83	    bool                               ee_b_conformance_passed{false};
84	};
