1	#pragma once
2	// INC-E (2026-07-14) -- Experiment-Phase-Strategy-Pattern: die 3 Experiment-Phasen
3	// (Kompositionale Joins Stufe 1/2/3) als benannte Strategy-Familie ueber dem ce-
4	// MergeStrategy-Discriminator. HEADER-ONLY, INERT: KEIN Konsument -- die Verdrahtung
5	// in V32Orchestrator::execute_messreihe (v32_orchestrator.hpp) bleibt Stufe G, NICHT hier.
6	// Hier NUR die Strategy-Huelle mit klarer API select_merge()/phase_name()/describe();
7	// der reale MergeAxis-Aufruf + CEB-Antrieb ist ebenfalls G.
8	//
9	// ============================================================================
10	// BENANNTE PATTERNS (zitierfaehig -- keine musterlosen Konstrukte)
11	// ============================================================================
12	//   @pattern GoF-Strategy
13	//     Jede Experiment-Phase kapselt EINEN austauschbaren Merge-/Kompositions-
14	//     Algorithmus hinter einer einheitlichen API. Die konkreten Strategies sind
15	//     gegen das ExperimentPhaseStrategy-Concept austauschbar (Family-of-Algorithms).
16	//     Primaerquelle: Gamma/Helm/Johnson/Vlissides, "Design Patterns: Elements of
17	//     Reusable Object-Oriented Software", Addison-Wesley 1994, Strategy S.315-323.
18	//
19	//   @pattern Policy-Based-Design (Compile-Time Strategy-Auswahl statt Runtime-Switch)
20	//     PhaseStrategyFor<MergeStrategy S> waehlt die konkrete Strategy per Non-Type-
21	//     Template-Parameter (Partial-Specialization-Dispatch, gespiegelt zu detail::
22	//     MergeImpl in anatomy/pruefling_merge.hpp:136-158). ZERO-COST, kein vtable,
23	//     kein Runtime-Switch im Hot-Path.
24	//     Primaerquelle: Alexandrescu, "Modern C++ Design: Generic Programming and
25	//     Design Patterns Applied", Addison-Wesley 2001, Kap. 1 (Policy-Based Design).
26	//
27	//   @pattern CRTP + Concept-Guard (statischer Dispatch, kein Runtime-Polymorphismus)
28	//     PhaseStrategyBase<Derived> ist die CRTP-Basis (static polymorphism: die Basis
29	//     leitet resolved_merge() an Derived::select_merge() weiter); das C++23-Concept
30	//     ExperimentPhaseStrategy erzwingt die Pflicht-API zur Compile-Zeit (static_assert
31	//     statt "missing method"-Diagnose). Konsistent zu topics/axis_base.hpp
32	//     (AxisBase-CRTP-Wurzel + AxisBaseConcept).
33	//     Primaerquellen: Coplien, "Curiously Recurring Template Patterns", C++ Report
34	//     7(2) 1995, S.24-27; Gregor/Jaervi/Siek/Stroustrup u.a., "Concepts: Linguistic
35	//     Support for Generic Programming in C++", OOPSLA 2006, S.291-310.
36	//
37	// Discriminator = comdare::cache_engine::anatomy::pruefling::MergeStrategy (Single-
38	// Source der 3 Stufen, anatomy/pruefling_merge.hpp:130-134) -- KEIN dupliziertes Enum.
39	//
40	// @task INC-E (A-E-Welle: Strategy-Pattern der Experiment-Configs)
41	// @related anatomy/pruefling_merge.hpp (MergeStrategy/MergeAxis/detail::MergeImpl)
42	// @related builder/commands/compare_engine_command.hpp (@command_pattern-Nachbarmuster)
43	// @related topics/axis_base.hpp (CRTP+Concept-Guard-Achsen -- Muster-Vorlage)
44	// @related reference_meta_driven_concept_hardening_pattern (Pattern-Fach-Benennung + Primaerquellen)
45	
46	#include <anatomy/pruefling_merge.hpp> // MergeStrategy (Discriminator, Single-Source der 3 Stufen)
47	
48	#include <concepts>
49	#include <string_view>
50	#include <type_traits>
51	
52	namespace comdare::diplomarbeit::messung_driver::v32::strategy {
53	
54	/// MergeStrategy-Alias auf die ce-Single-Source (anatomy/pruefling_merge.hpp) -- kein
55	/// eigenes Enum. Die 3 Werte: Stufe1_CeOnly / Stufe2_PrueflingReplace / Stufe3_FullJoin.
56	using MergeStrategy = ::comdare::cache_engine::anatomy::pruefling::MergeStrategy;
57	
58	// ─────────────────────────────────────────────────────────────────────────────
59	// (1) Concept-Guard -- die Pflicht-API jeder Experiment-Phasen-Strategy
60	// ─────────────────────────────────────────────────────────────────────────────
61	
62	/// ExperimentPhaseStrategy -- Compile-Time-Vertrag der Strategy-Familie (GoF-Strategy).
63	///
64	/// Jede konkrete Strategy MUSS statisch (compile-time, kein vtable) liefern:
65	///   - select_merge() -> MergeStrategy : WELCHE der 3 Kompositionalen Joins die Phase waehlt.
66	///   - phase_name()   -> string_view   : stabile Identitaet der Phase (== MergeStrategy-Name).
67	///   - describe()     -> string_view   : Kurzbeschreibung der Kompositions-Semantik.
68	///
69	/// Bei Verletzung: klare Concept-Diagnose statt "missing method" (analog AxisBaseConcept).
70	template <class S>
71	concept ExperimentPhaseStrategy = requires {
72	    { S::select_merge() } -> std::same_as<MergeStrategy>;
73	    { S::phase_name() } -> std::convertible_to<std::string_view>;
74	    { S::describe() } -> std::convertible_to<std::string_view>;
75	};
76	
77	// ─────────────────────────────────────────────────────────────────────────────
78	// (2) CRTP-Basis -- static polymorphism, gemeinsame Ableitungen ueber Derived
79	// ─────────────────────────────────────────────────────────────────────────────
80	
81	/// PhaseStrategyBase<Derived> -- CRTP-Wurzel der Strategy-Familie.
82	///
83	/// Static Dispatch: die Basis leitet auf die compile-time Merge-Wahl der abgeleiteten
84	/// Strategy weiter (Derived::select_merge()) -- KEINE virtuellen Funktionen, kein vtable.
85	/// Konkrete Strategies erben von dieser Basis und definieren die Policy (select_merge()).
86	/// Die Basis stellt daraus abgeleitete Praedikate bereit, die alle Strategies teilen.
87	template <class Derived>
88	struct PhaseStrategyBase {
89	    /// Static-polymorphe Aufloesung auf die Merge-Wahl der abgeleiteten Strategy.
90	    [[nodiscard]] static constexpr MergeStrategy resolved_merge() noexcept { return Derived::select_merge(); }
91	
92	    /// true, wenn die Phase KEINE Pruefling-Beteiligung hat (Stufe 1, CE-only Baseline).
93	    [[nodiscard]] static constexpr bool is_ce_only() noexcept {
94	        return Derived::select_merge() == MergeStrategy::Stufe1_CeOnly;
95	    }
96	
97	    /// true, wenn die Phase den Pruefling einbezieht (Stufe 2 ERSETZT oder Stufe 3 FullJoin).
98	    [[nodiscard]] static constexpr bool involves_pruefling() noexcept {
99	        return Derived::select_merge() != MergeStrategy::Stufe1_CeOnly;
100	    }
101	};
102	
103	// ─────────────────────────────────────────────────────────────────────────────
104	// (3) Die 3 konkreten Strategies -- je 1 Kompositionaler Join (Stufe 1/2/3)
105	// ─────────────────────────────────────────────────────────────────────────────
106	
107	/// Stufe 1 -- CE-only Baseline: KEINE Pruefling-Beteiligung.
108	/// Kompositions-Semantik: Achsenliste == ce-DefaultList (StufeOneAxis, pruefling_merge.hpp).
109	struct Stufe1CeOnlyStrategy final : PhaseStrategyBase<Stufe1CeOnlyStrategy> {
110	    [[nodiscard]] static constexpr MergeStrategy    select_merge() noexcept { return MergeStrategy::Stufe1_CeOnly; }
111	    [[nodiscard]] static constexpr std::string_view phase_name() noexcept { return "Stufe1_CeOnly"; }
112	    [[nodiscard]] static constexpr std::string_view describe() noexcept {
113	        return "CE-only Baseline -- keine Pruefling-Beteiligung; Achsenliste == ce-DefaultList (StufeOneAxis).";
114	    }
115	};
116	
117	/// Stufe 2 -- ERSETZT-mit-Fallback: die Pruefling-Varianten ERSETZEN die ce-DefaultList
118	/// pro Achse (Fallback = DefaultList, wenn der Pruefling-Slot leer ist).
119	/// Kompositions-Semantik: StufeTwoAxis via HasPruefling_v<Slot> (pruefling_merge.hpp).
120	struct Stufe2PrueflingReplaceStrategy final : PhaseStrategyBase<Stufe2PrueflingReplaceStrategy> {
121	    [[nodiscard]] static constexpr MergeStrategy select_merge() noexcept {
122	        return MergeStrategy::Stufe2_PrueflingReplace;
123	    }
124	    [[nodiscard]] static constexpr std::string_view phase_name() noexcept { return "Stufe2_PrueflingReplace"; }
125	    [[nodiscard]] static constexpr std::string_view describe() noexcept {
126	        return "ERSETZT-mit-Fallback -- Pruefling-Varianten ersetzen die ce-DefaultList pro Achse (StufeTwoAxis).";
127	    }
128	};
129	
130	/// Stufe 3 -- FullJoin: Union aller Default- + Pruefling-Varianten, dedupliziert.
131	/// Kompositions-Semantik: StufeThreeAxis == mp_unique<mp_append<...>> (pruefling_merge.hpp).
132	struct Stufe3FullJoinStrategy final : PhaseStrategyBase<Stufe3FullJoinStrategy> {
133	    [[nodiscard]] static constexpr MergeStrategy    select_merge() noexcept { return MergeStrategy::Stufe3_FullJoin; }
134	    [[nodiscard]] static constexpr std::string_view phase_name() noexcept { return "Stufe3_FullJoin"; }
135	    [[nodiscard]] static constexpr std::string_view describe() noexcept {
136	        return "FullJoin -- non-redundante Union aller Default- + Pruefling-Varianten (StufeThreeAxis, mp_unique).";
137	    }
138	};
139	
140	// ─────────────────────────────────────────────────────────────────────────────
141	// (4) Policy-Based Auswahl -- Discriminator -> konkrete Strategy (compile-time)
142	// ─────────────────────────────────────────────────────────────────────────────
143	
144	namespace detail {
145	/// PhaseStrategySelector<S> -- Partial-Specialization-Dispatch je MergeStrategy-Wert
146	/// (gespiegelt zu detail::MergeImpl in anatomy/pruefling_merge.hpp). Kein Runtime-Switch.
147	template <MergeStrategy S>
148	struct PhaseStrategySelector;
149	
150	template <>
151	struct PhaseStrategySelector<MergeStrategy::Stufe1_CeOnly> {
152	    using type = Stufe1CeOnlyStrategy;
153	};
154	
155	template <>
156	struct PhaseStrategySelector<MergeStrategy::Stufe2_PrueflingReplace> {
157	    using type = Stufe2PrueflingReplaceStrategy;
158	};
159	
160	template <>
161	struct PhaseStrategySelector<MergeStrategy::Stufe3_FullJoin> {
162	    using type = Stufe3FullJoinStrategy;
163	};
164	} // namespace detail
165	
166	/// PhaseStrategyFor<S> -- die konkrete Strategy zum Discriminator S (Policy-Based Design).
167	/// Beispiel: PhaseStrategyFor<MergeStrategy::Stufe3_FullJoin> == Stufe3FullJoinStrategy.
168	template <MergeStrategy S>
169	using PhaseStrategyFor = typename detail::PhaseStrategySelector<S>::type;
170	
171	// ─────────────────────────────────────────────────────────────────────────────
172	// (5) Header-lokale Concept-Guards -- die Familie validiert sich selbst (inert)
173	// ─────────────────────────────────────────────────────────────────────────────
174	
175	// Jede konkrete Strategy erfuellt den Familien-Vertrag (Concept-Guard greift).
176	static_assert(ExperimentPhaseStrategy<Stufe1CeOnlyStrategy>);
177	static_assert(ExperimentPhaseStrategy<Stufe2PrueflingReplaceStrategy>);
178	static_assert(ExperimentPhaseStrategy<Stufe3FullJoinStrategy>);
179	
180	// Discriminator-Roundtrip: die Policy-Auswahl liefert die zur MergeStrategy passende Strategy.
181	static_assert(PhaseStrategyFor<MergeStrategy::Stufe1_CeOnly>::select_merge() == MergeStrategy::Stufe1_CeOnly);
182	static_assert(PhaseStrategyFor<MergeStrategy::Stufe2_PrueflingReplace>::select_merge() ==
183	              MergeStrategy::Stufe2_PrueflingReplace);
184	static_assert(PhaseStrategyFor<MergeStrategy::Stufe3_FullJoin>::select_merge() == MergeStrategy::Stufe3_FullJoin);
185	
186	// CRTP-Basis leitet static-polymorph korrekt weiter.
187	static_assert(Stufe1CeOnlyStrategy::resolved_merge() == MergeStrategy::Stufe1_CeOnly);
188	static_assert(Stufe1CeOnlyStrategy::is_ce_only());
189	static_assert(Stufe2PrueflingReplaceStrategy::involves_pruefling());
190	static_assert(Stufe3FullJoinStrategy::involves_pruefling());
191	
192	// KEIN vtable / kein Runtime-Polymorphismus (statischer Dispatch, zero-cost).
193	static_assert(!std::is_polymorphic_v<Stufe1CeOnlyStrategy>);
194	static_assert(!std::is_polymorphic_v<Stufe2PrueflingReplaceStrategy>);
195	static_assert(!std::is_polymorphic_v<Stufe3FullJoinStrategy>);
196	static_assert(std::is_empty_v<Stufe1CeOnlyStrategy>);
197	static_assert(std::is_empty_v<Stufe2PrueflingReplaceStrategy>);
198	static_assert(std::is_empty_v<Stufe3FullJoinStrategy>);
199	
200	} // namespace comdare::diplomarbeit::messung_driver::v32::strategy
