18	/**
19	 * @brief CompareEngineCommand - vergleicht zwei ExecutionEngine-Resultate (F15)
20	 * @subsystem CEB
21	 * @command_pattern Compare
22	 * @phase_owner CEB
23	 *
24	 * Implementiert F15-Forschungsmission: vergleicht EE-A (CacheEngine) vs EE-B (PrtArt)
25	 * auf einer Permutation:
26	 * - Throughput-Ratio (PrtArt schneller? CE schneller? gleich?)
27	 * - Latency-Delta (Mikrosekunden-Differenz)
28	 * - Cache-Miss-Verbesserung (CLU/Footprint/H1-Hypothese)
29	 * - Memory-Footprint-Verhaeltnis (H2-Hypothese)
30	 *
31	 * Aufruf:
32	 *   auto cmp = CompareEngineCommand(result_ee_a, result_ee_b);
33	 *   cmp.execute(); // berechnet Vergleichs-Metriken
34	 *   auto verdict = cmp.verdict(); // {ee_a_wins, ee_b_wins, tie}
35	 */
36	class CompareEngineCommand : public ICommand {
37	public:
38	    enum class Verdict { EE_A_Wins, EE_B_Wins, Tie, InconclusiveData };
39	
40	    /// HH.3 Konfigurierbarer Verdict-Schwellwert (default 5%)
41	    static constexpr double kDefaultWinnerThreshold = 1.05;
42	    /// V33.A.3 Signifikanz-Niveau fuer Welch's t-Test (default alpha=0.05)
43	    static constexpr double kDefaultAlpha = 0.05;
44	
45	    CompareEngineCommand(ExecutionResult result_a, ExecutionResult result_b,
46	                         double winner_threshold = kDefaultWinnerThreshold, double alpha = kDefaultAlpha) noexcept
47	        : result_a_{result_a}, result_b_{result_b}, winner_threshold_{winner_threshold}, alpha_{alpha} {}
48	
49	    /// HH.3 H1/H2/H3 Hypothesen-Validierung (vereinfacht ohne Welch-T-Test)
50	    [[nodiscard]] bool h1_clu_validated() const noexcept {
51	        return result_a_.H1_clu_improvement >= 1.0; // CE-EE-A muss CLU verbessern
52	    }
53	    [[nodiscard]] bool h2_layout_validated() const noexcept { return result_a_.H2_layout_score >= 1.0; }
54	    [[nodiscard]] bool h3_inline_external_validated() const noexcept {
55	        // H3: Inline vs External Decision sinnvoll wenn Ratio in [0.2, 0.8]
56	        return result_a_.H3_inline_external_ratio >= 0.2 && result_a_.H3_inline_external_ratio <= 0.8;
57	    }
58	
59	    [[nodiscard]] std::string_view command_name() const noexcept override { return "CompareEngineCommand"; }
60	
61	    int execute() override {
62	        // V32.EE.1: konkrete Vergleichs-Logik
63	        if (!result_a_.success || !result_b_.success) {
64	            verdict_ = Verdict::InconclusiveData;
65	            return 1;
66	        }
67	
68	        // F15-Vergleich
69	        throughput_ratio_       = (result_b_.throughput_ops_per_sec > 0.0)
70	                                      ? result_a_.throughput_ops_per_sec / result_b_.throughput_ops_per_sec
71	                                      : 0.0;
72	        latency_delta_ns_       = (result_b_.latency_p99 - result_a_.latency_p99).count();
73	        cache_miss_improvement_ = (result_a_.total_cache_misses < result_b_.total_cache_misses)
74	                                      ? (result_b_.total_cache_misses - result_a_.total_cache_misses)
75	                                      : 0;
76	        memory_footprint_ratio_ = (result_b_.memory_footprint_bytes > 0)
77	                                      ? static_cast<double>(result_a_.memory_footprint_bytes) /
78	                                            static_cast<double>(result_b_.memory_footprint_bytes)
79	                                      : 0.0;
80	
81	        // V33.A.3 Welch's t-Test wenn Latency-Samples in beiden Ergebnissen
82	        // Wenn signifikant (p < alpha): wer kleinere Latenz hat gewinnt.
83	        // Wenn nicht signifikant: Tie. Fallback nur wenn keine Samples vorhanden.
84	        if (!result_a_.latency_samples_ns.empty() && !result_b_.latency_samples_ns.empty()) {
85	            welch_ = stats::welch_t_test(result_a_.latency_samples_ns, result_b_.latency_samples_ns);
86	            if (welch_.valid && welch_.p_value < alpha_) {
87	                verdict_ = (welch_.mean_a < welch_.mean_b) ? Verdict::EE_A_Wins // kleinere Latenz = EE_A schneller
88	                                                           : Verdict::EE_B_Wins;
89	            } else {
90	                verdict_ = Verdict::Tie;
91	            }
92	            return 0;
93	        }
94	
95	        // HH.3 Konfigurierbarer Schwellwert (Fallback ohne Samples)
96	        if (throughput_ratio_ > winner_threshold_) {
97	            verdict_ = Verdict::EE_A_Wins;
98	        } else if (throughput_ratio_ < (1.0 / winner_threshold_)) {
99	            verdict_ = Verdict::EE_B_Wins;
100	        } else {
101	            verdict_ = Verdict::Tie;
102	        }
103	        return 0;
104	    }
105	
106	    /// V33.A.3 Welch's t-Test Resultat (gueltig wenn beide ExecutionResults Samples haben)
107	    [[nodiscard]] const stats::WelchResult& welch() const noexcept { return welch_; }
108	
109	    [[nodiscard]] Verdict       verdict() const noexcept { return verdict_; }
110	    [[nodiscard]] double        throughput_ratio() const noexcept { return throughput_ratio_; }
111	    [[nodiscard]] long long     latency_delta_ns() const noexcept { return latency_delta_ns_; }
112	    [[nodiscard]] std::uint64_t cache_miss_improvement() const noexcept { return cache_miss_improvement_; }
113	    [[nodiscard]] double        memory_footprint_ratio() const noexcept { return memory_footprint_ratio_; }
114	
115	private:
116	    ExecutionResult    result_a_;
117	    ExecutionResult    result_b_;
