34	/// Ergebnis eines Konformitäts-Laufs — Quoten statt nur bool (V5-Design §6: „Konformitäts-Quoten").
35	struct ConformanceResult {
36	    std::uint64_t      cases_total  = 0; ///< Anzahl geprüfter Einzel-Zusicherungen
37	    std::uint64_t      cases_passed = 0; ///< davon bestanden
38	    std::uint64_t      first_fail   = 0; ///< 1-basierter Index der ersten verletzten Zusicherung (0 = keine)
39	    [[nodiscard]] bool passed() const noexcept { return cases_total > 0 && cases_passed == cases_total; }
40	};
