51	[[nodiscard]] inline AllocatorProxyProbeResult probe_allocator_proxy(anatomy::IDriveableTier& tier) noexcept {
52	    AllocatorProxyProbeResult r{};
53	    auto*                     proxy = dynamic_cast<anatomy::IAllocatorProxyTier*>(&tier);
54	    if (proxy == nullptr) return r;
55	    r.interface_present = true;
56	    proxy->tier_get_allocator(&r.proxy);
57	    r.identity_present    = (r.proxy.flags & (std::uint64_t{1} << 0u)) != 0u;
58	    r.stats_route_present = (r.proxy.flags & (std::uint64_t{1} << 1u)) != 0u;
59	    return r;
60	}
