62	/// run_conformance_gate — deterministische Randfall- + Zufallssequenz gegen std::map-Oracle.
63	/// `tier` wird VORHER geleert. Je Op verglichen: Rückgabe-Semantik (neu?/Treffer?/existierte?), Lookup-Wert, Größe.
64	/// noexcept: eine werfende Hülle verletzt den ABI-noexcept-Vertrag → gilt als nicht-konform.
65	[[nodiscard]] inline ConformanceResult run_conformance_gate(anatomy::IDriveableTier& tier, std::uint64_t seed = 42,
66	                                                            std::uint64_t n_random = 2000, bool wide_keys = false,
67	                                                            std::FILE* report = nullptr) noexcept {
68	    ConformanceResult r{};
69	    auto              check = [&](bool ok) noexcept {
70	        ++r.cases_total;
71	        if (ok) {
72	            ++r.cases_passed;
73	        } else if (r.first_fail == 0) {
74	            r.first_fail = r.cases_total;
75	        }
76	    };
77	    auto report_block = [&](char const* name, std::uint64_t before_total, std::uint64_t before_passed) noexcept {
78	        if (report == nullptr) return;
79	        auto const total_delta  = r.cases_total - before_total;
80	        auto const passed_delta = r.cases_passed - before_passed;
81	        std::fprintf(report, "    %s: %s (%llu/%llu)\n", name, (total_delta == passed_delta) ? "OK" : "FAIL",
82	                     static_cast<unsigned long long>(passed_delta), static_cast<unsigned long long>(total_delta));
83	    };
84	    auto report_skip = [&](char const* name, char const* why) noexcept {
85	        if (report == nullptr) return;
86	        std::fprintf(report, "    %s: SKIP (%s)\n", name, why);
87	    };
88	    try {
89	        std::map<std::uint64_t, std::uint64_t> oracle;
90	        DriveableMapView                       map{tier};
91	        map.clear();
92	
93	        // RF1 dagger-empty/find/count/contains: leeres Tier -> Lookup-Miss, Groesse 0, empty/count/contains false.
94	        auto const    rf1_total  = r.cases_total;
95	        auto const    rf1_passed = r.cases_passed;
96	        std::uint64_t v          = 123;
97	        check(map.at(7, v) == false);
98	        check(map.size() == 0);
99	        check(map.empty() == oracle.empty());
100	        check(map.contains(7) == oracle.contains(7));
101	        check(map.count(7) == oracle.count(7));
102	        report_block("RF1 dagger-empty/find/count/contains", rf1_total, rf1_passed);
103	
104	        // RF2 dagger-insert_or_assign/find: insert neu -> true; Lookup-Hit + korrekter Wert; Groesse 1.
105	        auto const rf2_total  = r.cases_total;
106	        auto const rf2_passed = r.cases_passed;
107	        check(map.insert_or_assign(7, 70) == true);
108	        oracle.insert_or_assign(7, 70);
109	        check(map.at(7, v) == true && v == 70);
110	        check(map.size() == oracle.size());
111	        report_block("RF2 dagger-insert_or_assign/find(new)", rf2_total, rf2_passed);
112	
113	        // RF3 dagger-insert_or_assign: insert Duplikat (Update) -> false; Wert aktualisiert; Groesse unveraendert.
114	        auto const rf3_total  = r.cases_total;
115	        auto const rf3_passed = r.cases_passed;
116	        check(map.insert_or_assign(7, 700) == false);
117	        oracle.insert_or_assign(7, 700);
118	        check(map.at(7, v) == true && v == 700);
119	        check(map.size() == oracle.size());
120	        report_block("RF3 dagger-insert_or_assign(update)", rf3_total, rf3_passed);
121	
122	        // RF4 dagger-erase/find/empty: erase existierend -> true; danach Miss; Groesse dekrementiert; empty nach letztem
123	        // erase.
124	        auto const rf4_total  = r.cases_total;
125	        auto const rf4_passed = r.cases_passed;
126	        check(map.erase(7) == true);
127	        oracle.erase(7);
128	        check(map.at(7, v) == false);
129	        check(map.size() == oracle.size());
130	        check(map.empty() == oracle.empty());
131	        check(oracle.find(7) == oracle.end());
132	        report_block("RF4 dagger-erase/find/empty", rf4_total, rf4_passed);
133	
134	        // RF5 dagger-erase: erase nicht-existent -> false; Groesse unveraendert.
135	        auto const rf5_total  = r.cases_total;
136	        auto const rf5_passed = r.cases_passed;
137	        check(map.erase(999) == false);
138	        check(map.size() == oracle.size());
139	        report_block("RF5 dagger-erase(miss)", rf5_total, rf5_passed);
140	
141	        auto lookup_matches_oracle = [&](std::uint64_t key) noexcept {
142	            auto const    it       = oracle.find(key);
143	            std::uint64_t got      = 0;
144	            bool const    tier_hit = map.at(key, got);
145	            check(tier_hit == (it != oracle.end()));
146	            if (it != oracle.end()) { check(got == it->second); }
147	        };
148	
149	        // RF6 dagger-contains/count/find: Hit- und Miss-Faelle explizit gegen std::map::contains/count/find.
150	        auto const rf6_total  = r.cases_total;
151	        auto const rf6_passed = r.cases_passed;
152	        check(map.insert_or_assign(11, 110) == true);
153	        oracle.insert_or_assign(11, 110);
154	        check(map.contains(11) == oracle.contains(11));
155	        check(map.count(11) == oracle.count(11));
156	        lookup_matches_oracle(11);
157	        check(map.contains(12) == oracle.contains(12));
158	        check(map.count(12) == oracle.count(12));
159	        lookup_matches_oracle(12);
160	        check(map.erase(11) == true);
161	        oracle.erase(11);
162	        lookup_matches_oracle(11);
163	        report_block("RF6 dagger-contains/count/find", rf6_total, rf6_passed);
164	
165	        // RF7 dagger-insert/emplace/try_emplace: host-seitig als lookup -> ggf. insert; vorhandene Werte bleiben alt.
166	        auto const rf7_total  = r.cases_total;
167	        auto const rf7_passed = r.cases_passed;
168	        check(map.insert_if_absent(17, 170) == oracle.insert({17, 170}).second);
169	        lookup_matches_oracle(17);
170	        check(map.insert_if_absent(17, 171) == oracle.insert({17, 171}).second);
171	        lookup_matches_oracle(17);
172	        check(map.insert_if_absent(18, 180) == oracle.emplace(18, 180).second);
173	        lookup_matches_oracle(18);
174	        check(map.insert_if_absent(18, 181) == oracle.emplace(18, 181).second);
175	        lookup_matches_oracle(18);
176	        check(map.insert_if_absent(19, 190) == oracle.try_emplace(19, 190).second);
177	        lookup_matches_oracle(19);
178	        check(map.insert_if_absent(19, 191) == oracle.try_emplace(19, 191).second);
179	        lookup_matches_oracle(19);
180	        check(map.size() == oracle.size());
181	        report_block("RF7 dagger-insert/emplace/try_emplace", rf7_total, rf7_passed);
182	
183	        // RF8 dagger-insert_or_assign/operator[]/at: direkte Upserts, Default-Insert 0 und at-hit/miss.
184	        auto const rf8_total  = r.cases_total;
185	        auto const rf8_passed = r.cases_passed;
186	        check(map.insert_or_assign(20, 200) == oracle.insert_or_assign(20, 200).second);
187	        lookup_matches_oracle(20);
188	        check(map.insert_or_assign(20, 201) == oracle.insert_or_assign(20, 201).second);
189	        lookup_matches_oracle(20);
190	
191	        std::uint64_t bracket = 999;
192	        auto const    op_new  = oracle[21];
193	        check(map.bracket(21, bracket) && bracket == op_new);
194	        check(map.size() == oracle.size());
195	        check(map.insert_or_assign(22, 220) == oracle.insert_or_assign(22, 220).second);
196	        auto const op_old = oracle[22];
197	        check(map.bracket(22, bracket) && bracket == op_old);
198	        check(map.size() == oracle.size());
199	
200	        std::uint64_t at_hit = 0;
201	        check(map.at(22, at_hit) && at_hit == oracle.at(22));
202	        bool oracle_at_miss_threw = false;
203	        try {
204	            (void)oracle.at(222);
205	        } catch (std::out_of_range const&) { oracle_at_miss_threw = true; }
206	        check(!map.at(222, at_hit) && oracle_at_miss_threw);
207	        report_block("RF8 dagger-insert_or_assign/operator[]/at", rf8_total, rf8_passed);
208	
209	        // RF9: Zufallssequenz ueber begrenzten Key-Raum (Kollisionen/Updates/Erases), je Schritt Lookup+Groesse.
210	        auto const      rf9_total  = r.cases_total;
211	        auto const      rf9_passed = r.cases_passed;
212	        std::mt19937_64 rng{seed};
213	        for (std::uint64_t i = 0; i < n_random; ++i) {
214	            std::uint64_t const key = rng() % 256;
215	            switch (rng() % 3) {
216	                case 0: { // insert/update
217	                    std::uint64_t const val      = rng();
218	                    bool const          was_new  = (oracle.find(key) == oracle.end());
219	                    bool const          tier_new = map.insert_or_assign(key, val);
220	                    oracle.insert_or_assign(key, val);
221	                    check(tier_new == was_new);
222	                    break;
223	                }
224	                case 1: { // lookup
225	                    auto const    it       = oracle.find(key);
226	                    std::uint64_t got      = 0;
227	                    bool const    tier_hit = map.at(key, got);
228	                    check(tier_hit == (it != oracle.end()));
229	                    if (it != oracle.end()) { check(got == it->second); }
230	                    break;
231	                }
232	                default: { // erase
233	                    bool const existed      = (oracle.find(key) != oracle.end());
234	                    bool const tier_existed = map.erase(key);
235	                    oracle.erase(key);
236	                    check(tier_existed == existed);
237	                    break;
238	                }
239	            }
240	            check(map.size() == oracle.size());
241	        }
242	        report_block("RF9 random-core(insert/find/erase/size)", rf9_total, rf9_passed);
243	
244	        // RF10 dagger-begin/end/lower_bound/upper_bound/equal_range/key_comp: geordnete Host-Synthese ueber
245	        // IScannableTier, falls das geladene Tier diese additive ABI-faehigkeit wirklich traegt.
246	        map.clear();
247	        oracle.clear();
248	        constexpr std::array<std::uint64_t, 5> order_keys{40u, 10u, 30u, 20u, 50u};
249	        for (auto const key : order_keys) {
250	            (void)map.insert_or_assign(key, key * 10u + 3u);
251	            oracle.insert_or_assign(key, key * 10u + 3u);
252	        }
253	
254	        if (!map.has_scanner()) {
255	            report_skip("RF10 dagger-begin/end", "ordnungs-Ops übersprungen (kein IScannableTier)");
256	            report_skip("RF11 dagger-lower_bound/upper_bound/equal_range",
257	                        "ordnungs-Ops übersprungen (kein IScannableTier)");
258	        } else {
259	            auto const probe = map.lower_bound(0u, oracle.size());
260	            if (probe.count == 0 && !oracle.empty()) {
261	                report_skip("RF10 dagger-begin/end",
262	                            "ordnungs-Ops übersprungen (IScannableTier liefert keine Records)");
263	                report_skip("RF11 dagger-lower_bound/upper_bound/equal_range",
264	                            "ordnungs-Ops übersprungen (IScannableTier liefert keine Records)");
265	            } else {
266	                auto check_scan_result = [&](auto const& got, std::uint64_t start_key,
267	                                             std::uint64_t max_count) noexcept {
268	                    std::uint64_t expected_count = 0;
269	                    std::uint64_t expected_sum   = 0;
270	                    for (auto it = oracle.lower_bound(start_key); it != oracle.end() && expected_count < max_count;
271	                         ++it) {
272	                        expected_sum += it->second;
273	                        ++expected_count;
274	                    }
275	                    check(got.count == expected_count);
276	                    check(got.checksum == expected_sum);
277	                };
278	
279	                auto const rf10_total  = r.cases_total;
280	                auto const rf10_passed = r.cases_passed;
281	                for (std::uint64_t prefix = 0; prefix <= oracle.size() + 1u; ++prefix) {
282	                    check_scan_result(map.lower_bound(0u, prefix), 0u, prefix);
283	                }
284	                check_scan_result(map.lower_bound(60u, 4u), 60u, 4u); // end(): groesser als max -> leere Range
285	                report_block("RF10 dagger-begin/end", rf10_total, rf10_passed);
286	
287	                auto const rf11_total  = r.cases_total;
288	                auto const rf11_passed = r.cases_passed;
289	                for (auto const key : std::array<std::uint64_t, 6>{5u, 10u, 25u, 30u, 50u, 60u}) {
290	                    check_scan_result(map.lower_bound(key, 1u), key, 1u); // lower_bound(key)
291	                    if (key != std::numeric_limits<std::uint64_t>::max()) {
292	                        auto const upper_start = oracle.contains(key) ? key + 1u : key;
293	                        check_scan_result(map.upper_bound(key, oracle.contains(key), 1u), upper_start,
294	                                          1u); // upper_bound/equal_range second fuer uint64-Probe-Keys
295	                    }
296	                }
297	                report_block("RF11 dagger-lower_bound/upper_bound/equal_range", rf11_total, rf11_passed);
298	            }
299	        }
300	        auto const rf12_total  = r.cases_total;
301	        auto const rf12_passed = r.cases_passed;
302	        auto const comp        = oracle.key_comp();
303	        check(comp(10u, 20u));
304	        check(!comp(20u, 10u));
305	        check(!comp(10u, 10u));
306	        report_block("RF12 dagger-key_comp(std::less<uint64_t>)", rf12_total, rf12_passed);
307	
308	        // RF13 dagger-clear/empty/find: clear -> Groesse 0; beliebiger Lookup-Miss; empty wahr.
309	        auto const rf13_total  = r.cases_total;
310	        auto const rf13_passed = r.cases_passed;
311	        map.clear();
312	        oracle.clear();
313	        check(map.size() == 0);
314	        check(map.at(42, v) == false);
315	        check(map.empty() == oracle.empty());
316	        report_block("RF13 dagger-clear/empty/find", rf13_total, rf13_passed);
317	
318	        if (wide_keys) {
319	            auto const                             rf14_total  = r.cases_total;
320	            auto const                             rf14_passed = r.cases_passed;
321	            constexpr std::array<std::uint64_t, 4> keys{0u, 65'536u, (1ull << 32u),
322	                                                        std::numeric_limits<std::uint64_t>::max()};
323	            for (auto const key : keys) {
324	                auto const val = key ^ 0xA5A5A5A5A5A5A5A5ull;
325	                check(map.insert_or_assign(key, val) == oracle.insert_or_assign(key, val).second);
326	                lookup_matches_oracle(key);
327	            }
328	            report_block("RF14 wide_keys opt-in", rf14_total, rf14_passed);
329	        } else {
330	            report_skip("RF14 wide_keys opt-in", "wide_keys=false");
331	        }
332	    } catch (...) {
333	        check(false); // werfende Hülle = nicht-konform
334	    }
335	    return r;
336	}
