407	struct ExperimentValidationResult {
408	    bool                     ok = true;
409	    std::vector<std::string> errors;
410	    std::vector<std::string> warnings;
411	    std::size_t              engines_checked    = 0;
412	    std::size_t              phases_checked     = 0;
413	    std::size_t              variants_checked   = 0; // gepruefte allowed_variants (0 = registry_dir leer / keine)
414	    std::size_t              categories_checked = 0; // gepruefte <category>-Namen (0 = keine deklariert)
415	};
