62	// Rekursive Suche nach einer Datei mit dem gegebenen Basename unterhalb von root (fuer den ${date}-Pfad).
63	static std::optional<fs::path> find_under(fs::path const& root, std::string const& basename) {
64	    if (!fs::exists(root)) { return std::nullopt; }
65	    for (auto const& e : fs::recursive_directory_iterator(root)) {
66	        if (e.is_regular_file() && e.path().filename() == basename) { return e.path(); }
67	    }
68	    return std::nullopt;
69	}
